class Account:
    def __init__(self, holder, balance):
        self.holder   = holder
        self.__balance = balance        # internal

    def deposit(self, amount):
        self.__balance = self.__balance + amount

    def show(self):
        print(self.holder, "balance:", self.__balance)

a = Account("Rahul", 1000)
a.deposit(500)
a.show()
