class Employee:
    def role(self):
        print("does the work")

class Manager(Employee):
    def role(self):               # overrides
        print("assigns the work")

class Intern(Employee):
    pass                          # keeps the parent version

for p in [Employee(), Manager(), Intern()]:
    p.role()

class Payroll:
    def calculate(self):
        pass                      # the parent only NAMES it

class Monthly(Payroll):
    def calculate(self):
        return 50000

class Hourly(Payroll):
    def calculate(self):
        return 250 * 160

for p in [Monthly(), Hourly()]:
    print(type(p).__name__, "->", p.calculate())
